from checked_integer import *
def integer_column_values(data: str, column: int) -> list[int]:
    if column < 0:
        raise ValueError
    values: list[int] = []
    lines: list[str] = data.splitlines()
    for line in lines:
        parts: list[str] = line.split('\t')
        if column >= len(parts):
            raise ValueError
        values.append(parse_int64_decimal(parts[column]))
    return values

def integer_values_reverse(values: list[int]) -> list[int]:
    return [values[i] for i in range(len(values) - 1, -1, -1)]

def float_values_scale(values: list[float], scale: float) -> list[float]:
    return [value * scale for value in values]

def string_values_copy(values: list[str]) -> list[str]:
    result: list[str] = []
    for value in values:
        result.append(value)
    return result

def integer_values_render(values: list[int]) -> str:
    parts: list[str] = []
    for value in values:
        parts.append(str(value))
    if len(parts) == 0:
        return ''
    return '\n'.join(parts) + '\n'
